pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 v1, uint256 v2, address actor) public {
        vm.assume(actor != address(0));
        vm.assume(v2 != v1); // bug-triggering domain; still wide

        // initialize the contract and set an initial MinSum (any actor, any value)
        vm.startPrank(actor);
        c.SetMinSum(v1);
        c.Initialized();
        vm.stopPrank();

        // after initialization, a further SetMinSum may revert (reference) or
        // succeed (mutant), but in the reference it can NEVER change MinSum.
        bool ok;
        vm.prank(actor);
        try c.SetMinSum(v2) { ok = true; } catch { ok = false; }

        // general rule: MinSum retains its pre-initialization value for EVERY input
        assertTrue(c.MinSum() == v1, "MinSum must stay frozen after initialization");
    }
}

