contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 val) public {
        // keep the value in the admissible domain: _val + 1 must not overflow
        val = bound(val, 0, type(uint256).max - 1);

        // drive c through SetMinSum with a fuzzed caller
        vm.prank(address(0xBEEF));
        c.SetMinSum(val);

        // General rule: after a successful SetMinSum(_val), MinSum() == _val.
        assertTrue(c.MinSum() == val);
    }
}

