pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract Logger {
    function AddMessage(address, uint256, string memory) public pure {}
}

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 amount, address actor) public {
        vm.assume(actor != address(0));
        amount = bound(amount, 1, type(uint256).max / 2);

        // Setup: configure a working log target. In the reference this succeeds;
        // in the mutant the inverted nonReentrant_ makes it always revert.
        Logger lg = new Logger();
        bool setupOk;
        try c.SetLogFile(address(lg)) { setupOk = true; } catch { setupOk = false; }

        // Rule: after setup, any actor may deposit any positive amount via Put (fallback).
        vm.deal(actor, amount);
        vm.prank(actor);
        bool putOk;
        (bool s, ) = address(c).call{value: amount}("");
        putOk = s;

        assertTrue(setupOk && putOk && c.Acc(actor).balance == amount);
    }
}

