pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 val) public {
        val = bound(val, 1, type(uint128).max);
        // Before initialization, SetMinSum(val) must succeed and store val.
        vm.prank(address(0xBEEF));
        bool okBefore;
        try c.SetMinSum(val) { okBefore = true; } catch { okBefore = false; }
        // After initialization, SetMinSum must revert, leaving MinSum unchanged.
        c.Initialized();
        vm.prank(address(0xBEEF));
        bool okAfter;
        try c.SetMinSum(val + 1) { okAfter = true; } catch { okAfter = false; }
        assertTrue(okBefore && c.MinSum() == val && !okAfter);
    }
}

